</span>
<span style="display:block;height:1px;background:#e2e5e9;margin:2px 0"></span>
<span style="font-weight:600;font-size:11px">Lower boundary of each sub‑region</span>
<label>R₁ lower: y = <input id="leftLowerInput" value="-x + 1"></label>
<label>R₂ lower: y = <input id="rightLowerInput" value="x + 1"></label>
<label>Vertical strip position x: <output id="stripXVal">-1</output>
  <input id="stripXInput" type="range" min="-2" max="2" step="0.05" value="-1"
   oninput="document.getElementById('stripXVal').value=this.value;update_stripX(+this.value)"></label>
<label><input id="viewModeInput" type="checkbox" checked onchange="toggle_viewMode(this.checked)"> Split into R₁ and R₂</label>
<span style="font-size:10px;color:#666;line-height:1.35">Tip: try <code>x^2 + 1</code> as the R₂ lower boundary — the curve, the shading and the inner limit all change together.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var BLUE = '#2ba4dd', PALE_B = '#cfe4f4', PALE_O = '#fbe2c0', RED = '#ef4b4b', INK = '#111';

var frame = setPlotFrame({ xDomain: [-3.6, 3.6], yDomain: [-3.15, 4.65], margin: 12 });
var draw = frame.draw;

var scaleCur = 1;
function scale() {
  return Math.max(0.42, Math.min(1.4, Math.min(frame.width / 660, frame.height / 505)));
}

/* ── region fills (sampled from the compiled boundary functions) ───────── */
var fillL = fillBetween('R1', { lower: '-x + 1', upper: '3', domain: [-2, 0], fill: PALE_B, opacity: 1, samples: 260 });
var fillR = fillBetween('R2', { lower: 'x + 1', upper: '3', domain: [0, 2], fill: PALE_O, opacity: 1, samples: 260 });

/* ── boundary curves ───────────────────────────────────────────────────── */
var curveL = plotFunction('lowL', { expr: '-x + 1', domain: [-2, 0], stroke: BLUE, width: 4, samples: 260 });
var curveR = plotFunction('lowR', { expr: 'x + 1', domain: [0, 2], stroke: BLUE, width: 4, samples: 260 });
var curveTop = plotFunction('top', { expr: '3', domain: [-2, 2], stroke: BLUE, width: 4, samples: 12 });

var gTop = draw.group();

/* ── state ─────────────────────────────────────────────────────────────── */
var leftFn = null, rightFn = null;
var leftSrc = '-x + 1', rightSrc = 'x + 1';
var stripX = -1;
var split = true;

function clampLower(fn) {
  return function (x) { var v = fn(x); return isFinite(v) ? Math.min(v, 3) : NaN; };
}

/* ── equation inputs ───────────────────────────────────────────────────── */
bindEquationInput('leftLowerInput',
  [{ handle: fillL, method: 'setLower' }, curveL],
  {
    variables: ['x'],
    onChange: function (fn, src) {
      leftFn = fn; leftSrc = src;
      fillL.setLower(clampLower(fn));
      refresh();
    }
  });

bindEquationInput('rightLowerInput',
  [{ handle: fillR, method: 'setLower' }, curveR],
  {
    variables: ['x'],
    onChange: function (fn, src) {
      rightFn = fn; rightSrc = src;
      fillR.setLower(clampLower(fn));
      refresh();
    }
  });

/* ── control handlers ──────────────────────────────────────────────────── */
function update_stripX(v) { stripX = v; drawOverlay(); }
function toggle_viewMode(on) { split = !!on; refresh(); }

/* ── fill colours + hover/click wiring (re-applied after every sample) ─── */
function styleFills() {
  var cR = split ? PALE_O : PALE_B;
  fillL.node.each(function () {
    this.fill(PALE_B).css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('R₁ : −2 ≤ x ≤ 0,  ' + leftSrc + ' ≤ y ≤ 3', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Sub-region R₁',
          'For every x between −2 and 0 the vertical strip starts on the line y = ' + leftSrc +
          ' and ends at y = 3. That is exactly the inner integral ∫ from ' + leftSrc + ' to 3 of f dy.');
      });
  });
  fillR.node.each(function () {
    this.fill(cR).css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('R₂ : 0 ≤ x ≤ 2,  ' + rightSrc + ' ≤ y ≤ 3', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Sub-region R₂',
          'For x between 0 and 2 the bottom of the strip is y = ' + rightSrc + ', a different formula from the left half. ' +
          'A single iterated integral cannot use two different lower limits, so the region is split at x = 0.');
      });
  });
}

/* ── overlay: axes, labels, strips, readout ────────────────────────────── */
function mlabel(s, wx, wy, size, color, italic) {
  var t = gTop.text(s).font({
    family: 'Georgia,"Times New Roman",serif', size: size,
    anchor: 'middle', style: (italic === false ? 'normal' : 'italic')
  }).fill(color || INK);
  t.attr({
    'paint-order': 'stroke', stroke: '#fff',
    'stroke-width': Math.max(2, 3.2 * scaleCur), 'stroke-linejoin': 'round'
  });
  t.cx(plotX(wx)).cy(plotY(wy));
  return t;
}

function lowerAt(x) {
  var f = (x < 0) ? leftFn : rightFn;
  if (!f) return NaN;
  var v = f(x);
  return isFinite(v) ? v : NaN;
}

function drawStrip(x, opacity, primary) {
  var lo = lowerAt(x);
  if (!isFinite(lo)) return;
  var loc = Math.min(lo, 3);
  var w = Math.max(1.4, (primary ? 3.0 : 2.2) * scaleCur);
  var ln = gTop.line(plotX(x), plotY(loc), plotX(x), plotY(3))
    .stroke({ color: RED, width: w, linecap: 'round' }).opacity(opacity);
  if (primary) {
    gTop.circle(Math.max(3, 5 * scaleCur)).fill(RED).center(plotX(x), plotY(loc));
    gTop.circle(Math.max(3, 5 * scaleCur)).fill(RED).center(plotX(x), plotY(3));
  }
  ln.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('Inner integral at x = ' + x.toFixed(2) + ' :  y from ' +
        loc.toFixed(2) + ' up to 3', e);
    })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The vertical strip = the inner integral',
        'At x = ' + x.toFixed(2) + ' the strip runs from the lower boundary y = ' +
        (x < 0 ? leftSrc : rightSrc) + ' (value ' + loc.toFixed(2) + ') up to y = 3. ' +
        'Integrating f over this strip gives the inner integral; sweeping x gives the outer one.');
    });
}

function drawOverlay() {
  scaleCur = scale();
  var S = scaleCur;
  gTop.clear();

  var lw = Math.max(1.2, 2.2 * S);
  var fsBig = Math.max(9, 18 * S);
  var fsTick = Math.max(8, 15 * S);
  var fsRead = Math.max(7, 12.4 * S);

  /* x-axis */
  var y0 = plotY(0), xEnd = plotX(3.15);
  gTop.line(plotX(-3.35), y0, xEnd, y0).stroke({ color: INK, width: lw });
  gTop.polygon([[xEnd, y0 - 6 * S], [xEnd + 16 * S, y0], [xEnd, y0 + 6 * S]]).fill(INK);
  mlabel('x', 3.05, 0.52, fsBig);

  /* y-axis */
  var x0 = plotX(0), yTop = plotY(4.12);
  gTop.line(x0, plotY(-1.02), x0, yTop).stroke({ color: INK, width: lw });
  gTop.polygon([[x0 - 6 * S, yTop], [x0, yTop - 16 * S], [x0 + 6 * S, yTop]]).fill(INK);
  mlabel('y', 0.32, 4.02, fsBig);

  /* ticks */
  [-2, 2].forEach(function (v) {
    gTop.line(plotX(v), y0, plotX(v), y0 - Math.max(5, 9 * S)).stroke({ color: INK, width: lw });
  });
  mlabel('−2', -2, -0.48, fsTick, INK, false);
  mlabel('0', -0.24, -0.48, fsTick, INK, false);
  mlabel('2', 2, -0.48, fsTick, INK, false);

  /* dashed divider on the y-axis inside the region */
  if (split) {
    var l0 = leftFn ? leftFn(0) : 1, r0 = rightFn ? rightFn(0) : 1;
    var base = Math.min(isFinite(l0) ? l0 : 1, isFinite(r0) ? r0 : 1);
    base = Math.min(base, 3);
    gTop.line(x0, plotY(base), x0, plotY(3))
      .stroke({ color: '#1b7fb5', width: Math.max(1.4, 2.4 * S), dasharray: (6 * S) + ',' + (4 * S) });
  }

  /* red strips: the movable one + the companion on the other half */
  var partner = (stripX < 0) ? 0.7 : -1;
  drawStrip(partner, 0.5, false);
  drawStrip(stripX, 1, true);

  /* boundary + region labels */
  mlabel('y = 3', -1.05, 3.45, fsBig);
  mlabel('y = 3', 1.05, 3.45, fsBig);
  mlabel('y = ' + leftSrc, -2.72, 1.42, fsBig);
  mlabel('y = ' + rightSrc, 2.72, 1.42, fsBig);
  if (split) {
    mlabel('R₁', -0.62, 2.35, fsBig * 1.05);
    mlabel('R₂', 0.62, 2.35, fsBig * 1.05);
  } else {
    mlabel('R', -0.55, 2.35, fsBig * 1.1);
  }

  /* ── readout panel ───────────────────────────────────────────────── */
  var bx = plotX(-3.45), by = plotY(-1.25), bw = plotX(3.45) - bx, bh = plotY(-3.05) - by;
  var box = gTop.rect(bw, bh).move(bx, by).radius(5 * S)
    .fill('#f8f9fb').stroke({ color: '#dfe3e8', width: Math.max(0.8, 1 * S) });
  box.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('The sum of two iterated integrals — click for why', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Why a sum of two integrals?',
        'The inner limits of a type-I integral are the lower and upper boundary curves. Here the upper one is always y = 3, ' +
        'but the lower one is ' + leftSrc + ' for x < 0 and ' + rightSrc + ' for x > 0. ' +
        'Since one formula cannot describe both, R is split at x = 0 and the double integral becomes the sum shown.');
    });

  var a1 = NaN, a2 = NaN;
  if (leftFn && rightFn) {
    try { a1 = integrateSimpson(function (x) { var v = leftFn(x); return isFinite(v) ? Math.max(0, 3 - v) : 0; }, -2, 0, 200); } catch (e) { a1 = NaN; }
    try { a2 = integrateSimpson(function (x) { var v = rightFn(x); return isFinite(v) ? Math.max(0, 3 - v) : 0; }, 0, 2, 200); } catch (e) { a2 = NaN; }
  }
  var lo = lowerAt(stripX);

  function rline(s, wy, bold, color) {
    var t = gTop.text(s).font({
      family: 'Georgia,"Times New Roman",serif', size: fsRead,
      anchor: 'middle', weight: bold ? '600' : 'normal'
    }).fill(color || '#1c2833');
    t.cx(plotX(0)).cy(plotY(wy));
    return t;
  }
  rline('∬ f dA  =  ∫₋₂⁰ ∫[ ' + leftSrc + ' → 3 ] f dy dx   +   ∫₀² ∫[ ' + rightSrc + ' → 3 ] f dy dx', -1.62, true, '#0b3d5c');
  rline('area R₁ = ' + (isFinite(a1) ? a1.toFixed(3) : '—') +
    '     area R₂ = ' + (isFinite(a2) ? a2.toFixed(3) : '—') +
    '     total = ' + (isFinite(a1 + a2) ? (a1 + a2).toFixed(3) : '—'), -2.14, false, '#2b4a5c');
  rline('strip at x = ' + stripX.toFixed(2) + ' :  y from ' +
    (isFinite(lo) ? Math.min(lo, 3).toFixed(2) : '—') + ' to 3   (lower limit = ' +
    (stripX < 0 ? leftSrc : rightSrc) + ')', -2.66, false, '#a13a1e');
}

function refresh() {
  if (!leftFn || !rightFn) return;
  styleFills();
  drawOverlay();
}

document.addEventListener('fig-resize', function () { refresh(); });

/* ── demo step player ──────────────────────────────────────────────────── */
var steps = [
  {
    title: 'The region R',
    narration: 'R is the triangle bounded above by y = 3 and below by the two lines y = −x + 1 and y = x + 1, with vertices (−2, 3), (0, 1) and (2, 3).',
    state: { viewMode: 'Whole region R', stripX: -1 }
  },
  {
    title: 'A vertical strip on the left',
    narration: 'Fix x between −2 and 0. The red strip runs from the lower boundary y = −x + 1 up to y = 3, so the inner integral is ∫ from −x+1 to 3 dy.',
    state: { viewMode: 'Split into R₁ and R₂', stripX: -1 }
  },
  {
    title: 'Crossing x = 0',
    narration: 'Drag the strip past the y-axis: the top stays at y = 3, but the bottom now follows y = x + 1. The lower limit changes formula exactly at x = 0.',
    state: { viewMode: 'Split into R₁ and R₂', stripX: 0.7 }
  },
  {
    title: 'Two integrals, one region',
    narration: 'Because no single formula gives the bottom of every strip, R is written as R₁ ∪ R₂ and the double integral becomes ∫₋₂⁰∫_{−x+1}^{3} + ∫₀²∫_{x+1}^{3}.',
    state: { viewMode: 'Split into R₁ and R₂', stripX: 1.5 }
  },
  {
    title: 'Edit a boundary',
    narration: 'Type a new lower boundary for either half — say x^2 + 1 on the right. The blue curve, the shaded area and the inner limit all update together, confirming that the limit IS the boundary.',
    state: { viewMode: 'Split into R₁ and R₂', stripX: 1 }
  }
];
var stepIdx = 0;

function showStepText() {
  document.getElementById('demoTitle').textContent = steps[stepIdx].title;
  document.getElementById('demoNarration').textContent = steps[stepIdx].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
}

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[stepIdx].state;
  var cb = document.getElementById('viewModeInput');
  cb.checked = (st.viewMode !== 'Whole region R');
  split = cb.checked;
  var sl = document.getElementById('stripXInput');
  sl.value = st.stripX;
  document.getElementById('stripXVal').value = st.stripX;
  stripX = +st.stripX;
  showStepText();
  refresh();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ── init: faithful default view (split, strip at x = −1) ──────────────── */
showStepText();
refresh();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: When the lower boundary of a plane region is given by two different formulas on either side of x = 0, the region must be split into two type-I sub-regions and the double integral written as a sum of two iterated integrals.
KEY INSIGHT (what students should walk away understanding): The inner limits of a type-I double integral are literally the upper and lower boundary curves; when the lower boundary switches formula at x = 0, you must switch integrals there too.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
