// @FIGURE_CODE_BEGIN
var BLUE = '#2ba4dd', PALE_B = '#cfe6f5', PALE_O = '#fbe4c4', RED = '#f2545b', INK = '#111';

var frame = setPlotFrame({ xDomain: [-3.75, 3.75], yDomain: [-1.15, 4.75], margin: 8 });
var draw = frame.draw;

function U() { return Math.max(18, Math.min(frame.sx, frame.sy)); }
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

/* ── region fills (sampled from the compiled boundary functions) ───────── */
var fillL = fillBetween('R1', { lower: '-x + 1', upper: '3', domain: [-2, 0], fill: PALE_B, opacity: 1, samples: 260 });
var fillR = fillBetween('R2', { lower: 'x + 1', upper: '3', domain: [0, 2], fill: PALE_O, opacity: 1, samples: 260 });

/* ── boundary curves ───────────────────────────────────────────────────── */
var curveL = plotFunction('lowL', { expr: '-x + 1', domain: [-2, 0], stroke: BLUE, width: 4, samples: 260 });
var curveR = plotFunction('lowR', { expr: 'x + 1', domain: [0, 2], stroke: BLUE, width: 4, samples: 260 });
var curveTop = plotFunction('top', { expr: '3', domain: [-2, 2], stroke: BLUE, width: 4, samples: 12 });

var gTop = draw.group();

/* ── state ─────────────────────────────────────────────────────────────── */
var leftFn = null, rightFn = null;
var leftSrc = '-x + 1', rightSrc = 'x + 1';
var stripX = -1;
var split = true;
var showDivider = false;

function clampLower(fn) {
  return function (x) { var v = fn(x); return isFinite(v) ? Math.min(v, 3) : NaN; };
}

/* ── equation inputs ───────────────────────────────────────────────────── */
bindEquationInput('leftLowerInput',
  [{ handle: fillL, method: 'setLower' }, curveL],
  {
    variables: ['x'],
    onChange: function (fn, src) {
      leftFn = fn; leftSrc = src;
      fillL.setLower(clampLower(fn));
      refresh();
    }
  });

bindEquationInput('rightLowerInput',
  [{ handle: fillR, method: 'setLower' }, curveR],
  {
    variables: ['x'],
    onChange: function (fn, src) {
      rightFn = fn; rightSrc = src;
      fillR.setLower(clampLower(fn));
      refresh();
    }
  });

/* ── control handlers ──────────────────────────────────────────────────── */
function update_stripX(v) { stripX = v; drawOverlay(); updateReadout(); }
function toggle_viewMode(on) { split = !!on; refresh(); }

/* ── fill colours + hover/click wiring (re-applied after every sample) ─── */
function styleFills() {
  var cR = split ? PALE_O : PALE_B;
  fillL.node.each(function () {
    this.fill(PALE_B).css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('R₁ : −2 ≤ x ≤ 0,   ' + leftSrc + ' ≤ y ≤ 3', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Sub-region R₁',
          'For every x between −2 and 0 the vertical strip starts on y = ' + leftSrc +
          ' and ends at y = 3. That is exactly the inner integral ∫ from ' + leftSrc + ' to 3 of f dy.');
      });
  });
  fillR.node.each(function () {
    this.fill(cR).css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('R₂ : 0 ≤ x ≤ 2,   ' + rightSrc + ' ≤ y ≤ 3', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Sub-region R₂',
          'For x between 0 and 2 the bottom of the strip is y = ' + rightSrc + ', a different formula from the left half. ' +
          'A single iterated integral cannot use two different lower limits, so the region is split at x = 0.');
      });
  });
}

/* ── overlay: axes, labels, strips ─────────────────────────────────────── */
function mlabel(s, wx, wy, size, color, italic) {
  var t = gTop.text(s).font({
    family: 'Georgia,"Times New Roman",serif', size: size,
    anchor: 'middle', style: (italic === false ? 'normal' : 'italic')
  }).fill(color || INK);
  t.attr({
    'paint-order': 'stroke', stroke: '#fff',
    'stroke-width': Math.max(2, size * 0.14), 'stroke-linejoin': 'round'
  });
  t.cx(plotX(wx)).cy(plotY(wy));
  return t;
}

function lowerAt(x) {
  var f = (x < 0) ? leftFn : rightFn;
  if (!f) return NaN;
  var v = f(x);
  return isFinite(v) ? v : NaN;
}

function drawStrip(x, primary) {
  var lo = lowerAt(x);
  if (!isFinite(lo)) return;
  var loc = Math.min(lo, 3);
  if (loc > 2.995) return;
  var u = U();
  var w = Math.max(1.4, (primary ? 0.042 : 0.036) * u);
  gTop.line(plotX(x), plotY(loc), plotX(x), plotY(3))
    .stroke({ color: RED, width: w, linecap: 'butt' });
  var hit = gTop.line(plotX(x), plotY(loc), plotX(x), plotY(3))
    .stroke({ color: RED, width: Math.max(10, 0.16 * u), opacity: 0 })
    .attr('pointer-events', 'stroke').css('cursor', 'pointer');
  hit.on('mousemove', function (e) {
    showTooltip('Inner integral at x = ' + x.toFixed(2) + ' :  y from ' + loc.toFixed(2) + ' up to 3', e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The vertical strip = the inner integral',
        'At x = ' + x.toFixed(2) + ' the strip runs from the lower boundary y = ' +
        (x < 0 ? leftSrc : rightSrc) + ' (value ' + loc.toFixed(2) + ') up to y = 3. ' +
        'Integrating f over this strip gives the inner integral; sweeping x gives the outer one.');
    });
}

function drawOverlay() {
  gTop.clear();
  var u = U();

  var lw = Math.max(1.2, 0.036 * u);
  var bw = Math.max(2, 0.060 * u);
  var fsBig = clamp(0.30 * u, 9, 32);
  var fsReg = clamp(0.36 * u, 10, 38);
  var fsTick = clamp(0.29 * u, 9, 30);
  var ah = 0.20 * u, ahw = 0.075 * u;

  /* re-stroke boundaries at the current scale */
  [curveL, curveR, curveTop].forEach(function (h) {
    h.node.each(function () { this.stroke({ width: bw }); });
  });

  /* x-axis */
  var y0 = plotY(0), xEnd = plotX(3.45);
  gTop.line(plotX(-3.6), y0, xEnd, y0).stroke({ color: INK, width: lw });
  gTop.polygon([[xEnd, y0 - ahw], [xEnd + ah, y0], [xEnd, y0 + ahw]]).fill(INK);
  mlabel('x', 3.40, 0.45, fsBig);

  /* y-axis */
  var x0 = plotX(0), yTop = plotY(4.40);
  gTop.line(x0, plotY(-0.92), x0, yTop).stroke({ color: INK, width: lw });
  gTop.polygon([[x0 - ahw, yTop], [x0, yTop - ah], [x0 + ahw, yTop]]).fill(INK);
  mlabel('y', 0.30, 4.28, fsBig);

  /* ticks (above the axis, as in the source) */
  [-2, 2].forEach(function (v) {
    gTop.line(plotX(v), y0 - 0.15 * u, plotX(v), y0).stroke({ color: INK, width: lw });
  });
  mlabel('−2', -2, -0.33, fsTick, INK, false);
  mlabel('2', 2, -0.33, fsTick, INK, false);
  mlabel('0', 0.17, -0.33, fsTick, INK, false);

  /* dashed divider (only revealed in the later demo steps) */
  if (split && showDivider) {
    var l0 = leftFn ? leftFn(0) : 1, r0 = rightFn ? rightFn(0) : 1;
    var base = Math.min(isFinite(l0) ? l0 : 1, isFinite(r0) ? r0 : 1);
    base = Math.min(base, 3);
    gTop.line(x0, plotY(base), x0, plotY(3))
      .stroke({ color: '#1b7fb5', width: Math.max(1.3, 0.032 * u), dasharray: (0.09 * u) + ',' + (0.06 * u) });
  }

  /* red strips: the movable one and its companion on the other half */
  var partner = (stripX < 0) ? 0.7 : -1;
  drawStrip(partner, false);
  drawStrip(stripX, true);

  /* boundary + region labels */
  mlabel('y = 3', -1.21, 3.35, fsBig);
  mlabel('y = 3', 0.99, 3.35, fsBig);
  mlabel('y = ' + leftSrc, -2.70, 1.93, fsBig);
  mlabel('y = ' + rightSrc, 2.70, 1.93, fsBig);
  if (split) {
    mlabel('R₁', -0.68, 2.52, fsReg);
    mlabel('R₂', 0.62, 2.52, fsReg);
  } else {
    mlabel('R', -0.05, 2.52, fsReg);
  }
}

/* ── side-panel readout (recomputed from the compiled boundaries) ──────── */
function updateReadout() {
  var a1 = NaN, a2 = NaN;
  if (leftFn && rightFn) {
    try { a1 = integrateSimpson(function (x) { var v = leftFn(x); return isFinite(v) ? Math.max(0, 3 - v) : 0; }, -2, 0, 200); } catch (e) { a1 = NaN; }
    try { a2 = integrateSimpson(function (x) { var v = rightFn(x); return isFinite(v) ? Math.max(0, 3 - v) : 0; }, 0, 2, 200); } catch (e) { a2 = NaN; }
  }
  var lo = lowerAt(stripX);
  document.getElementById('readIntegral').textContent =
    '∬ f dA = ∫₋₂⁰ ∫[' + leftSrc + ' → 3] f dy dx + ∫₀² ∫[' + rightSrc + ' → 3] f dy dx';
  document.getElementById('readStrip').textContent =
    'strip at x = ' + stripX.toFixed(2) + ' : y from ' +
    (isFinite(lo) ? Math.min(lo, 3).toFixed(2) : '—') + ' to 3  (lower limit = ' +
    (stripX < 0 ? leftSrc : rightSrc) + ')';
  document.getElementById('readArea').textContent =
    'area R₁ = ' + (isFinite(a1) ? a1.toFixed(3) : '—') +
    ' · area R₂ = ' + (isFinite(a2) ? a2.toFixed(3) : '—') +
    ' · total = ' + (isFinite(a1 + a2) ? (a1 + a2).toFixed(3) : '—');
}

function refresh() {
  if (!leftFn || !rightFn) return;
  styleFills();
  drawOverlay();
  updateReadout();
}

document.addEventListener('fig-resize', function () { refresh(); });

/* ── demo step player ──────────────────────────────────────────────────── */
var steps = [
  {
    title: 'The region R',
    narration: 'R is the triangle bounded above by y = 3 and below by the two lines y = −x + 1 and y = x + 1, with vertices (−2, 3), (0, 1) and (2, 3). It is shown already coloured as the two halves R₁ (x < 0) and R₂ (x > 0).',
    state: { split: true, stripX: -1, divider: false }
  },
  {
    title: 'One region, or two?',
    narration: 'Untick the split to see R as a single shape: nothing about the region changes. The split at x = 0 is pure bookkeeping for the limits of integration.',
    state: { split: false, stripX: -1, divider: false }
  },
  {
    title: 'A vertical strip on the left',
    narration: 'Fix x between −2 and 0. The red strip runs from the lower boundary y = −x + 1 up to y = 3, so the inner integral is ∫ from −x+1 to 3 f dy.',
    state: { split: true, stripX: -1, divider: false }
  },
  {
    title: 'Crossing x = 0',
    narration: 'Drag the strip past the y-axis: the top stays at y = 3, but the bottom now follows y = x + 1. The dashed divider marks where the lower limit changes formula.',
    state: { split: true, stripX: 0.7, divider: true }
  },
  {
    title: 'Two integrals — and edit a boundary',
    narration: 'No single formula gives the bottom of every strip, so ∬ f dA = ∫₋₂⁰∫_{−x+1}³ + ∫₀²∫_{x+1}³. Now type a new lower boundary, say x^2 + 1 on the right: curve, shading and inner limit all update together.',
    state: { split: true, stripX: 1, divider: true }
  }
];
var stepIdx = 0;

function showStepText() {
  document.getElementById('demoTitle').textContent = steps[stepIdx].title;
  document.getElementById('demoNarration').textContent = steps[stepIdx].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
}

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[stepIdx].state;
  var cb = document.getElementById('viewModeInput');
  cb.checked = !!st.split;
  split = cb.checked;
  showDivider = !!st.divider;
  var sl = document.getElementById('stripXInput');
  sl.value = st.stripX;
  document.getElementById('stripXVal').value = st.stripX;
  stripX = +st.stripX;
  showStepText();
  refresh();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ── init: step 1 state = the faithful default view ────────────────────── */
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: When the lower boundary of a plane region is given by two different formulas on either side of x = 0, the region must be split into two type-I sub-regions and the double integral written as a sum of two iterated integrals.
KEY INSIGHT (what students should walk away understanding): The inner limits of a type-I double integral are literally the upper and lower boundary curves; when the lower boundary switches formula at x = 0, you must switch integrals there too.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
