// @FIGURE_CODE_BEGIN
var BLUE = '#2ba4dd', PALE_B = '#cfe6f5', PALE_O = '#fbe4c4', RED = '#f2545b', INK = '#111';

var frame = setPlotFrame({ xDomain: [-3.75, 3.75], yDomain: [-1.15, 4.75], margin: 8 });
var draw = frame.draw;

function U() { return Math.max(18, Math.min(frame.sx, frame.sy)); }
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

/* ── pretty-printer: raw input source → typeset math text ──────────────── */
var SUP = { '0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴', '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹' };
function prettyExpr(src) {
  var s = String(src == null ? '' : src).trim();
  if (!s) return s;
  // integer powers → unicode superscripts
  s = s.replace(/\s*\^\s*\(?\s*(-?\d+)\s*\)?/g, function (m, d) {
    var neg = d.charAt(0) === '-';
    var digits = neg ? d.slice(1) : d, out = '';
    for (var i = 0; i < digits.length; i++) out += (SUP[digits.charAt(i)] || digits.charAt(i));
    return (neg ? '⁻' : '') + out;
  });
  s = s.replace(/\s+/g, '').replace(/\*/g, '·').replace(/\//g, '⁄');
  var out = '';
  for (var i = 0; i < s.length; i++) {
    var c = s.charAt(i);
    if (c === '+' || c === '-') {
      var prev = out.replace(/\s+$/, '').slice(-1);
      var binary = prev !== '' && !/[+\u2212·⁄(,^]/.test(prev);
      var ch = (c === '-') ? '−' : '+';
      out += binary ? (' ' + ch + ' ') : ch;
    } else out += c;
  }
  return out;
}

/* ── region fills (sampled from the compiled boundary functions) ───────── */
